import { mutation, query, type QueryCtx } from './_generated/server'
import { v } from 'convex/values'
import type { Doc, Id } from './_generated/dataModel'
import { assertServerSecret } from './lib/serverSecret'

/**
 * Events with tap-to-RSVP. Server-only (`*WithSecret`), reached through
 * lib/convex/events-bridge.ts. RSVP tokens are generated by the Next server and only
 * leave through `listSendTargetsWithSecret` (to build SMS links); no other function
 * returns them.
 */

const MAX_GUESTS = 10
const audience = v.union(v.literal('all'), v.literal('group'), v.literal('custom'))
const status = v.union(v.literal('draft'), v.literal('published'), v.literal('cancelled'))
const response = v.union(v.literal('yes'), v.literal('no'), v.literal('maybe'))

const eventFields = {
  title: v.string(),
  description: v.optional(v.string()),
  starts_at: v.number(),
  ends_at: v.optional(v.number()),
  location: v.optional(v.string()),
  capacity: v.optional(v.number()),
  audience,
  group_id: v.optional(v.string()),
  rsvp_closes_at: v.optional(v.number()),
  status,
}

function clampGuests(n: number | undefined): number {
  const x = Math.floor(Number(n ?? 0))
  return Number.isFinite(x) && x > 0 ? Math.min(x, MAX_GUESTS) : 0
}

function seats(r: Pick<Doc<'event_rsvps'>, 'response' | 'guests'>): number {
  return r.response === 'yes' ? 1 + clampGuests(r.guests) : 0
}

function eventOut(e: Doc<'events'>) {
  return { ...e, id: e._id, created_at: e._creationTime }
}

async function rsvpsFor(ctx: QueryCtx, eventId: Id<'events'>) {
  return ctx.db
    .query('event_rsvps')
    .withIndex('by_event', (q) => q.eq('event_id', eventId))
    .collect()
}

function tally(rows: Doc<'event_rsvps'>[]) {
  const t = { yes: 0, headcount: 0, guests: 0, no: 0, maybe: 0, noReply: 0, invited: 0, total: rows.length }
  for (const r of rows) {
    if (r.invited_at) t.invited++
    if (r.response === 'yes') {
      t.yes++
      t.guests += clampGuests(r.guests)
      t.headcount += seats(r)
    } else if (r.response === 'no') t.no++
    else if (r.response === 'maybe') t.maybe++
    else t.noReply++
  }
  return t
}

function deadline(e: Doc<'events'>): number {
  return e.rsvp_closes_at && e.rsvp_closes_at < e.starts_at ? e.rsvp_closes_at : e.starts_at
}

function firstName(u: Doc<'users'> | null): string {
  const first = u?.first_name?.trim() || u?.full_name?.trim() || ''
  return first.split(/\s+/)[0] || 'there'
}

export const listEventsWithSecret = query({
  args: { secret: v.string(), limit: v.optional(v.number()) },
  returns: v.any(),
  handler: async (ctx, { secret, limit }) => {
    assertServerSecret(secret)
    const take = Math.min(Math.max(limit ?? 200, 1), 500)
    const events = await ctx.db.query('events').withIndex('by_starts_at').order('desc').take(take)
    const out = []
    for (const e of events) out.push({ ...eventOut(e), tally: tally(await rsvpsFor(ctx, e._id)) })
    return out
  },
})

/** One event with its invitees (names and phones, no tokens). */
export const getEventWithSecret = query({
  args: { secret: v.string(), id: v.string() },
  returns: v.any(),
  handler: async (ctx, { secret, id }) => {
    assertServerSecret(secret)
    const eventId = ctx.db.normalizeId('events', id)
    if (!eventId) return null
    const event = await ctx.db.get('events', eventId)
    if (!event) return null
    const rows = await rsvpsFor(ctx, eventId)
    const rsvps = []
    for (const r of rows) {
      const user = await ctx.db.get('users', r.user_id)
      rsvps.push({
        id: r._id,
        user_id: r.user_id,
        name: user?.full_name ?? 'Unknown',
        phone: user?.phone,
        membership_id: user?.membership_id,
        sms_opt_out: Boolean(user?.sms_opt_out),
        response: r.response,
        guests: r.guests,
        responded_at: r.responded_at,
        invited_at: r.invited_at,
        reminder_sent_at: r.reminder_sent_at,
      })
    }
    return { event: eventOut(event), rsvps }
  },
})

export const createEventWithSecret = mutation({
  args: { secret: v.string(), created_by: v.string(), ...eventFields },
  returns: v.string(),
  handler: async (ctx, { secret, ...fields }) => {
    assertServerSecret(secret)
    const id = await ctx.db.insert('events', { ...fields, updated_at: Date.now() })
    return id
  },
})

export const updateEventWithSecret = mutation({
  args: { secret: v.string(), id: v.id('events'), ...eventFields },
  returns: v.null(),
  handler: async (ctx, { secret, id, ...fields }) => {
    assertServerSecret(secret)
    const existing = await ctx.db.get('events', id)
    if (!existing) throw new Error('Event not found')
    // Optional fields left out must be cleared, so replace rather than patch.
    await ctx.db.replace(id, { ...fields, created_by: existing.created_by, updated_at: Date.now() })
    return null
  },
})

/** Add invitees who aren't on the list yet. Tokens come from the caller (crypto-random). */
export const addInviteesWithSecret = mutation({
  args: {
    secret: v.string(),
    event_id: v.id('events'),
    invitees: v.array(v.object({ user_id: v.string(), token: v.string() })),
  },
  returns: v.object({ added: v.number() }),
  handler: async (ctx, { secret, event_id, invitees }) => {
    assertServerSecret(secret)
    if (!(await ctx.db.get('events', event_id))) throw new Error('Event not found')
    let added = 0
    const now = Date.now()
    for (const item of invitees) {
      const userId = ctx.db.normalizeId('users', item.user_id)
      if (!userId) continue
      const existing = await ctx.db
        .query('event_rsvps')
        .withIndex('by_event_user', (q) => q.eq('event_id', event_id).eq('user_id', userId))
        .first()
      if (existing) continue
      const clash = await ctx.db
        .query('event_rsvps')
        .withIndex('by_token', (q) => q.eq('token', item.token))
        .first()
      if (clash) continue
      await ctx.db.insert('event_rsvps', { event_id, user_id: userId, token: item.token, guests: 0, created_at: now })
      added++
    }
    return { added }
  },
})

export const removeInviteeWithSecret = mutation({
  args: { secret: v.string(), rsvp_id: v.id('event_rsvps') },
  returns: v.null(),
  handler: async (ctx, { secret, rsvp_id }) => {
    assertServerSecret(secret)
    await ctx.db.delete(rsvp_id)
    return null
  },
})

/** Server-only: invitees to text, with their token so the server can build each link. */
export const listSendTargetsWithSecret = query({
  args: { secret: v.string(), event_id: v.id('events'), rsvp_ids: v.array(v.string()) },
  returns: v.any(),
  handler: async (ctx, { secret, event_id, rsvp_ids }) => {
    assertServerSecret(secret)
    const out = []
    for (const raw of rsvp_ids) {
      const id = ctx.db.normalizeId('event_rsvps', raw)
      if (!id) continue
      const r = await ctx.db.get('event_rsvps', id)
      if (!r || r.event_id !== event_id) continue
      const user = await ctx.db.get('users', r.user_id)
      out.push({
        rsvp_id: r._id,
        user_id: r.user_id,
        token: r.token,
        name: user?.full_name ?? 'Member',
        first_name: firstName(user),
        phone: user?.phone,
        sms_opt_out: Boolean(user?.sms_opt_out),
        invited_at: r.invited_at,
        response: r.response,
      })
    }
    return out
  },
})

export const markSentWithSecret = mutation({
  args: {
    secret: v.string(),
    rsvp_ids: v.array(v.id('event_rsvps')),
    kind: v.union(v.literal('invite'), v.literal('reminder')),
  },
  returns: v.null(),
  handler: async (ctx, { secret, rsvp_ids, kind }) => {
    assertServerSecret(secret)
    const now = Date.now()
    for (const id of rsvp_ids) {
      const r = await ctx.db.get('event_rsvps', id)
      if (!r) continue
      await ctx.db.patch(id, kind === 'invite' ? { invited_at: r.invited_at ?? now } : { reminder_sent_at: now })
    }
    return null
  },
})

/** Public page context for `/e/<token>`. Never returns the token or other people's data. */
export const getRsvpByTokenWithSecret = query({
  args: { secret: v.string(), token: v.string() },
  returns: v.any(),
  handler: async (ctx, { secret, token }) => {
    assertServerSecret(secret)
    const r = await ctx.db
      .query('event_rsvps')
      .withIndex('by_token', (q) => q.eq('token', token))
      .first()
    if (!r) return null
    const event = await ctx.db.get('events', r.event_id)
    if (!event || event.status === 'draft') return null
    const user = await ctx.db.get('users', r.user_id)
    const all = await rsvpsFor(ctx, event._id)
    const headcount = all.reduce((n, x) => n + seats(x), 0)
    return {
      first_name: firstName(user),
      event: {
        title: event.title,
        description: event.description,
        starts_at: event.starts_at,
        ends_at: event.ends_at,
        location: event.location,
        capacity: event.capacity,
        rsvp_closes_at: event.rsvp_closes_at,
        status: event.status,
      },
      response: r.response,
      guests: r.guests,
      others_headcount: headcount - seats(r),
    }
  },
})

/**
 * Record an answer, by token (public page) or by event + user (signed-in member).
 * Capacity and deadline are enforced here, inside the transaction.
 */
export const respondRsvpWithSecret = mutation({
  args: {
    secret: v.string(),
    token: v.optional(v.string()),
    event_id: v.optional(v.string()),
    user_id: v.optional(v.string()),
    response,
    guests: v.number(),
  },
  returns: v.any(),
  handler: async (ctx, { secret, token, event_id, user_id, response, guests }) => {
    assertServerSecret(secret)
    let r: Doc<'event_rsvps'> | null = null
    if (token) {
      r = await ctx.db
        .query('event_rsvps')
        .withIndex('by_token', (q) => q.eq('token', token))
        .first()
    } else if (event_id && user_id) {
      const eid = ctx.db.normalizeId('events', event_id)
      const uid = ctx.db.normalizeId('users', user_id)
      if (eid && uid) {
        r = await ctx.db
          .query('event_rsvps')
          .withIndex('by_event_user', (q) => q.eq('event_id', eid).eq('user_id', uid))
          .first()
      }
    }
    if (!r) return { ok: false, error: 'This invitation was not found.' }
    const event = await ctx.db.get('events', r.event_id)
    if (!event || event.status === 'draft') return { ok: false, error: 'This invitation was not found.' }
    if (event.status === 'cancelled') return { ok: false, error: 'This event has been cancelled.' }
    if (Date.now() >= deadline(event)) return { ok: false, error: 'RSVPs for this event are closed.' }

    const g = response === 'yes' ? clampGuests(guests) : 0
    if (response === 'yes' && event.capacity && event.capacity > 0) {
      const all = await rsvpsFor(ctx, event._id)
      const others = all.reduce((n, x) => n + (x._id === r!._id ? 0 : seats(x)), 0)
      if (others + 1 + g > event.capacity) {
        const left = Math.max(0, event.capacity - others)
        return {
          ok: false,
          full: left === 0,
          error: left === 0 ? 'Sorry, this event is full.' : `Only ${left} place${left === 1 ? '' : 's'} left. Bring fewer guests.`,
        }
      }
    }
    await ctx.db.patch(r._id, { response, guests: g, responded_at: Date.now() })
    return { ok: true }
  },
})

/** A member's upcoming published events with their answer. */
export const listMyEventsWithSecret = query({
  args: { secret: v.string(), user_id: v.string() },
  returns: v.any(),
  handler: async (ctx, { secret, user_id }) => {
    assertServerSecret(secret)
    const uid = ctx.db.normalizeId('users', user_id)
    if (!uid) return []
    const now = Date.now()
    const rows = await ctx.db
      .query('event_rsvps')
      .withIndex('by_user', (q) => q.eq('user_id', uid))
      .collect()
    const out = []
    for (const r of rows) {
      const event = await ctx.db.get('events', r.event_id)
      if (!event || event.status !== 'published') continue
      if ((event.ends_at ?? event.starts_at) < now) continue
      const all = await rsvpsFor(ctx, event._id)
      const headcount = all.reduce((n, x) => n + seats(x), 0)
      out.push({
        event_id: event._id,
        title: event.title,
        description: event.description,
        starts_at: event.starts_at,
        ends_at: event.ends_at,
        location: event.location,
        capacity: event.capacity,
        rsvp_closes_at: event.rsvp_closes_at,
        status: event.status,
        response: r.response,
        guests: r.guests,
        others_headcount: headcount - seats(r),
      })
    }
    out.sort((a, b) => a.starts_at - b.starts_at)
    return out
  },
})
